import{_ as a,c as r,o,a4 as t}from"./chunks/framework.BU14wsQo.js";const n="/ai/daily/2026-06-17/news_01kv9r22etexzb9jgq1phbn4qf.avif",i="/ai/daily/2026-06-17/news_01kv9pm2f5exzb9jejztr1gj14.avif",l="/ai/daily/2026-06-17/news_01kv9pmk32exzb9jf34agx98zy.avif",s="/ai/daily/2026-06-17/news_01kv9r7sq2exzb9jjwf2h1pwh4.mp4",h="/ai/daily/2026-06-17/news_01kv9r52xwexzb9jhykhz0za0z.avif",c="/ai/daily/2026-06-17/news_01kv9r5fptexzb9jj7n1z0rddf.avif",_=JSON.parse('{"title":"AI大事件 2026/6/17","description":"AI大事件 2026/6/17 - 陈老板的百宝箱 AI 大事件日报，追踪模型发布、AI 产品、前沿研究、开源工具、安全政策与行业动态。","frontmatter":{"linkTitle":"06-17 AI大事件","title":"AI大事件 2026/6/17","weight":15,"breadcrumbs":false,"comments":true,"description":""},"headers":[],"relativePath":"ai/daily/cn/2026-06/2026-06-17.md","filePath":"AI/daily/cn/2026-06/2026-06-17.md","lastUpdated":1782113545000}'),p={name:"ai/daily/cn/2026-06/2026-06-17.md"};function d(m,e,u,b,f,k){return o(),r("div",null,[...e[0]||(e[0]=[t(`<h1 align="center">2026-06-17 AI大事件</h1><h2 id="今日摘要" tabindex="-1"><strong>今日摘要</strong> <a class="header-anchor" href="#今日摘要" aria-label="Permalink to &quot;**今日摘要**&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>克劳德核心提示词大幅更新、Grok办公辅助插件一键生成PPT推动产品能力与工作流继续演进 🚀</span></span>
<span class="line"><span>梯度算法新研究解决LoRA难题、智能体技能组合暴露严重漏洞展示研究侧对推理、数据与科学问题的持续推进 🧠</span></span>
<span class="line"><span>G7国家或将共享前沿AI模型、创意软件巨头发布年度报告让资本、监管与基础设施变化成为产业焦点 ⚖️</span></span>
<span class="line"><span>高性能极轻量级内存向量库开源、多语言语音生成模型正式发布继续把关键能力下沉给开发者 🛠️</span></span>
<span class="line"><span>人类亟需在爆发前建立验证体系、Okara首发网红智能体带来值得跟踪的实践观察与行业讨论 ( •̀ ω •́ )</span></span>
<span class="line"><span>今天的共同信号是：模型能力正在加速进入真实产品，但来源核验、成本和工程质量仍决定落地上限 (๑•̀ㅂ•́)و✧</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="模型与产品更新" tabindex="-1">模型与产品更新 <a class="header-anchor" href="#模型与产品更新" aria-label="Permalink to &quot;模型与产品更新&quot;">​</a></h2><h3 id="_1-克劳德核心提示词大幅更新" tabindex="-1">1. 克劳德核心提示词大幅更新 <a class="header-anchor" href="#_1-克劳德核心提示词大幅更新" aria-label="Permalink to &quot;1. 克劳德核心提示词大幅更新&quot;">​</a></h3><p>克劳德核心迎来 提示词精简方案 优化。新版上线了 🚀 知识库管理功能。多语言 SDK 升级 ✨ 核心模型版本。系统现在 🧐 能让推理过程更直观。安全模块能 🤖 更好防御恶意指令。 来源：<a href="https://github.com/Piebald-AI/claude-code-system-prompts/releases/tag/v2.1.174" target="_blank" rel="noreferrer">GitHub</a></p><h3 id="_2-grok-办公辅助插件一键生成-ppt" tabindex="-1">2. Grok 办公辅助插件一键生成 PPT <a class="header-anchor" href="#_2-grok-办公辅助插件一键生成-ppt" aria-label="Permalink to &quot;2. Grok 办公辅助插件一键生成 PPT&quot;">​</a></h3><p>办公软件 推出全新工具插件 供大家体验。用户 🚀 输入大纲即可一键生成演示文稿。软件能在本地 ⚡️ 直接完成叙事逻辑优化。智能工具 (^_−)☆ 简直是打工人救星。全新算力 🤖 正在全面改变传统办公方式。 来源：<a href="https://x.ai/news" target="_blank" rel="noreferrer">x.ai</a></p><h3 id="_3-qwen-robotnav-面向智能体导航系统的可扩展导航模型" tabindex="-1">3. Qwen-RobotNav：面向智能体导航系统的可扩展导航模型 <a class="header-anchor" href="#_3-qwen-robotnav-面向智能体导航系统的可扩展导航模型" aria-label="Permalink to &quot;3. Qwen-RobotNav：面向智能体导航系统的可扩展导航模型&quot;">​</a></h3><p>Qwen 发布 Qwen-RobotNav，基于 Qwen3-VL 在 15.6M 样本上训练，统一了视觉语言导航、目标导航、目标跟踪、自动驾驶和具身问答五个领域，无需修改架构即可在推理时切换任务模式和观察参数。模型在多项基准取得 SOTA：VLN-CE RxR 成功率 76.5%，HM3Dv2 目标导航 75.6%（仅 RGB），EVT-Bench 跟踪率 90.0%，NAVSIM PDMS 91.4，以及三项 EQA 新标杆。模型暴露四个可调轴（视觉 token 预算、时间衰减、相机权重、帧采样模式）。作为智能体系统的一部分，上层规划器 Qwen3.7-Plus 在 EXPRESS-Bench 上提升 15.4%，导航步数减少 … 🚀 来源：<a href="https://qwen.ai/blog?id=qwen-robotmanip" target="_blank" rel="noreferrer">qwen.ai</a>、<a href="https://qwen.ai/blog?id=qwen-robotworld" target="_blank" rel="noreferrer">qwen.ai</a></p><h3 id="_4-成本砍半-字节跳动推出-seedance-2-0-mini-视频生成模型" tabindex="-1">4. 成本砍半，字节跳动推出 Seedance 2.0 Mini 视频生成模型 <a class="header-anchor" href="#_4-成本砍半-字节跳动推出-seedance-2-0-mini-视频生成模型" aria-label="Permalink to &quot;4. 成本砍半，字节跳动推出 Seedance 2.0 Mini 视频生成模型&quot;">​</a></h3><p>字节跳动火山引擎旗下火山方舟体验中心于 6 月 15 日上线 Seedance 2.0 Mini 视频生成模型，计划近期开放 API。该模型比 Seedance 2.0 Fast 快 2 倍，输出质量相当。图生视频定价 0.023 元/千 tokens，视频生视频 0.014 元/千 tokens，720P 规格下单秒生成成本约 0.5 元，较 Seedance 2.0 标准版降低约一半。模型面向电商内容生产、营销素材批量生成、UGC 创作及特效玩法等高频率、大规模视频生成场景。 🚀 来源：<a href="https://www.ithome.com/0/964/672.htm" target="_blank" rel="noreferrer">ithome.com</a></p><h3 id="_5-教育部-阳光志愿-信息服务系统全新升级上线-智能筛选志愿-数据权威可信" tabindex="-1">5. 教育部“阳光志愿”信息服务系统全新升级上线：智能筛选志愿，数据权威可信 <a class="header-anchor" href="#_5-教育部-阳光志愿-信息服务系统全新升级上线-智能筛选志愿-数据权威可信" aria-label="Permalink to &quot;5. 教育部“阳光志愿”信息服务系统全新升级上线：智能筛选志愿，数据权威可信&quot;">​</a></h3><p>教育部“阳光志愿”信息服务系统今日全新升级上线，依托招生、学籍、就业等海量官方数据，免费为考生和家长提供志愿填报服务。系统支持 31 个省区市本专科普通批次志愿筛选，输入高考成绩、位次及个性化条件即可快速生成合理参考方案。AI 助手“智慧小招”24 小时在线解答政策规则。平台数据由高校直接报送、官方核验，真实可靠。同时推出专业倾向测评和 21 项生涯测评工具，帮助学生认清特长、规划未来。 🚀 来源：<a href="https://www.ithome.com/0/964/675.htm" target="_blank" rel="noreferrer">ithome.com</a></p><h3 id="_6-google-cloud-推出-okf-v0-1-供应商中立的-markdown-规范-为-ai-智能体提供结构化上下文" tabindex="-1">6. Google Cloud 推出 OKF v0.1：供应商中立的 Markdown 规范，为 AI 智能体提供结构化上下文 <a class="header-anchor" href="#_6-google-cloud-推出-okf-v0-1-供应商中立的-markdown-规范-为-ai-智能体提供结构化上下文" aria-label="Permalink to &quot;6. Google Cloud 推出 OKF v0.1：供应商中立的 Markdown 规范，为 AI 智能体提供结构化上下文&quot;">​</a></h3><p>Google Cloud 发布 Open Knowledge Format (OKF) v0.1，一种供应商中立的 Markdown 规范，为 AI 智能体提供结构化上下文知识。OKF 将知识表示为带 YAML 前置元数据的 markdown 文件目录，每个概念对应一个文件，通过 <code>type</code>、<code>title</code>、<code>description</code> 等少量保留字段实现互操作。无需专有服务、SDK 或运行时，目录可托管在 GitHub、以 tarball 传输或挂载到任意文件系统。OKF 旨在解决组织内部知识碎片化问题——表结构、指标定义、runbook 等散落在不同 catalog 和 wiki 中，各厂商方案互不兼容。遵循最少意见原则，只强制… 来源：<a href="https://www.marktechpost.com/2026/06/16/google-cloud-introduces-open-knowledge-format-okf-a-vendor-neutral-markdown-spec-for-giving-ai-agents-curated-context" target="_blank" rel="noreferrer">marktechpost.com</a></p><h3 id="_7-ai-版支付宝官宣开启邀测-右滑打开-阿宝-官方放出-100-个邀请码" tabindex="-1">7. AI 版支付宝官宣开启邀测：右滑打开“阿宝”，官方放出 100 个邀请码 <a class="header-anchor" href="#_7-ai-版支付宝官宣开启邀测-右滑打开-阿宝-官方放出-100-个邀请码" aria-label="Permalink to &quot;7. AI 版支付宝官宣开启邀测：右滑打开“阿宝”，官方放出 100 个邀请码&quot;">​</a></h3><p>支付宝今日开启 AI 版邀测，用户可右滑进入新版界面，在对话框或语音中输入指令，由“阿宝”助手代办事项。以查询公积金为例，阿宝自动匹配对应小程序和服务入口，用户点击确认即可完成，将多步跳转折叠为一句指令。所有涉及资金变动和支付的环节均需用户本人确认。首批放出 100 个邀请码。 🚀 来源：<a href="https://www.ithome.com/0/964/691.htm" target="_blank" rel="noreferrer">ithome.com</a></p><h3 id="_8-小米-mimo-claw-正式版发布-旗舰模型-金山办公-全新订阅服务上线" tabindex="-1">8. 小米 MiMo Claw 正式版发布：旗舰模型+金山办公，全新订阅服务上线 <a class="header-anchor" href="#_8-小米-mimo-claw-正式版发布-旗舰模型-金山办公-全新订阅服务上线" aria-label="Permalink to &quot;8. 小米 MiMo Claw 正式版发布：旗舰模型+金山办公，全新订阅服务上线&quot;">​</a></h3><p>小米推出云端轻量化 Claw 类产品 MiMo Claw 正式版，搭载与 OpenClaw 框架深度适配的 MiMo-V2.5-Pro 旗舰模型。该模型原生兼容 MCP 工具调用协议，内置百万级超长上下文，支持单会话千次以上连续工具调用；依托 MTP 三层解码架构，在 OpenClaw 标准 Agent 工作流中吞吐效率提升约 3 倍。ClawEval 测试中任务达标率（Pass³）达 63.8%，Token 消耗较同类产品降低 40%-60%。联动金山办公生态，提供 Word、Excel、PPT、PDF 等格式的 AI 生成、预览与在线编辑一站式服务。免费用户每日单次体验时长从 1 小时升级至 4 小时，面向高频用户推出 TokenPla… 🚀 来源：<a href="https://mp.weixin.qq.com/s/N5ac768a8LkhEjOVpkR1dQ" target="_blank" rel="noreferrer">mp.weixin.qq.com</a></p><h3 id="_9-subagent-让模型把琐碎任务委托出去" tabindex="-1">9. Subagent：让模型把琐碎任务委托出去 <a class="header-anchor" href="#_9-subagent-让模型把琐碎任务委托出去" aria-label="Permalink to &quot;9. Subagent：让模型把琐碎任务委托出去&quot;">​</a></h3><p>OpenRouter 推出 openrouter:subagent 服务器工具，允许前沿模型在生成过程中将独立的琐碎任务（如文档总结、结构化数据提取、文本重格式化）委托给更小、更便宜、更快的 worker 模型执行，从而节省前沿模型的 token 消耗。 🚀 来源：<a href="https://openrouter.ai/blog/announcements/subagent-server-tool" target="_blank" rel="noreferrer">openrouter.ai</a></p><h3 id="_10-midjourney-v8-1-推出-draft-mode-草稿模式与新功能预览" tabindex="-1">10. Midjourney V8.1 推出 Draft mode 草稿模式与新功能预览 <a class="header-anchor" href="#_10-midjourney-v8-1-推出-draft-mode-草稿模式与新功能预览" aria-label="Permalink to &quot;10. Midjourney V8.1 推出 Draft mode 草稿模式与新功能预览&quot;">​</a></h3><p>Midjourney V8.1 的 Draft mode 草稿模式每次生成 24 张低分辨率低质量图片。用户可对任意图片点击 &quot;Vary&quot;，将其渲染为全质量、全分辨率版本。草稿任务消耗的快速小时数减半。 🚀 来源：<a href="https://updates.midjourney.com/draft-mode-for-v8-1-and-new-feature-previews" target="_blank" rel="noreferrer">updates.midjourney.com</a></p><h3 id="_11-grok-for-powerpoint-发布-在-microsoft-powerpoint-内直接生成和编辑幻灯片" tabindex="-1">11. Grok for PowerPoint 发布：在 Microsoft PowerPoint 内直接生成和编辑幻灯片 <a class="header-anchor" href="#_11-grok-for-powerpoint-发布-在-microsoft-powerpoint-内直接生成和编辑幻灯片" aria-label="Permalink to &quot;11. Grok for PowerPoint 发布：在 Microsoft PowerPoint 内直接生成和编辑幻灯片&quot;">​</a></h3><p>xAI 于 6 月 16 日发布 Grok for PowerPoint，作为免费 Microsoft 365 插件上线。用户无需离开应用即可利用 Grok 将大纲转为完整幻灯片，进行内容研究、撰写、排版，并支持添加单张幻灯片、调整样式主题、重构章节。插件还能调用 Grok 连接器，从邮件或 SharePoint 中获取信息。该插件同样适用于 Word 和 Excel。 🚀 来源：<a href="https://x.ai/news/introducing-powerpoint-addin" target="_blank" rel="noreferrer">x.ai</a></p><h3 id="_12-谷歌正式推出安卓-17-系统" tabindex="-1">12. 谷歌正式推出安卓 17 系统 <a class="header-anchor" href="#_12-谷歌正式推出安卓-17-系统" aria-label="Permalink to &quot;12. 谷歌正式推出安卓 17 系统&quot;">​</a></h3><p>新系统搭载 多任务新工具 惊艳亮相。谷歌把全新的 智能模型 🚀 深度集成。全新的 (^_−)☆ 系统带来很多重磅升级。多窗口模式 ✨ 切换起来非常顺滑。安全防护全面 🛡️ 补齐系统最后一环。 来源：<a href="https://blog.google/products-and-platforms/platforms/android/android-17-features/" target="_blank" rel="noreferrer">Google Blog</a></p><h3 id="_13-copilot-cowork-全球正式可用-支持多模型" tabindex="-1">13. Copilot Cowork 全球正式可用，支持多模型 <a class="header-anchor" href="#_13-copilot-cowork-全球正式可用-支持多模型" aria-label="Permalink to &quot;13. Copilot Cowork 全球正式可用，支持多模型&quot;">​</a></h3><p>Copilot Cowork 现已全球正式可用，并支持多模型！ 每个组织都可以让长期运行的智能体处理复杂的多步骤任务，基于你组织的独特知识和专有技术。 <a href="https://www.microsoft.com/en-us/microsoft-365/blog/2026/06/16/copilot-cowork-is-now-generally-available/?v=15" target="_blank" rel="noreferrer">https://www.microsoft.com/en-us/microsoft-365/blog/2026/06/16/copilot-cowork-is-now-generally-available/?v=15</a> 🚀 来源：<a href="https://www.microsoft.com/en-us/microsoft-365/blog/2026/06/16/copilot-cowork-is-now-generally-available/" target="_blank" rel="noreferrer">Microsoft</a></p><h2 id="前沿研究" tabindex="-1">前沿研究 <a class="header-anchor" href="#前沿研究" aria-label="Permalink to &quot;前沿研究&quot;">​</a></h2><h3 id="_1-梯度算法新研究解决-lora-难题" tabindex="-1">1. 梯度算法新研究解决 LoRA 难题 <a class="header-anchor" href="#_1-梯度算法新研究解决-lora-难题" aria-label="Permalink to &quot;1. 梯度算法新研究解决 LoRA 难题&quot;">​</a></h3><p>技术人员发布 解决缩放难题 成果。团队发现梯度更新易出现 📉 分布偏斜。新架构将更新与奇异值 🧊 进行解耦。该方法能够显著 🚀 提升算法收敛速度。全新方案进一步缩小了全量微调差距。 来源：<a href="https://arxiv.org/abs/2606.16454" target="_blank" rel="noreferrer">arxiv.org</a></p><h3 id="_2-智能体技能组合暴露严重漏洞" tabindex="-1">2. 智能体技能组合暴露严重漏洞 <a class="header-anchor" href="#_2-智能体技能组合暴露严重漏洞" aria-label="Permalink to &quot;2. 智能体技能组合暴露严重漏洞&quot;">​</a></h3><p>学者指出 复杂任务风险 藏在细节中。多层级组合技能会让核心数据 ✨ 泄露。业内发布 全新评估框架 助力检测防线。测试表明组合攻击成功率 😲 竟然近九成。我们不能只盯着 ╮(￣ ▽ ￣)╭ 单个模型。 来源：<a href="https://arxiv.org/abs/2606.15242" target="_blank" rel="noreferrer">arxiv.org</a></p><h3 id="_3-临床-ai-深度推理预测问诊失败" tabindex="-1">3. 临床 AI 深度推理预测问诊失败 <a class="header-anchor" href="#_3-临床-ai-深度推理预测问诊失败" aria-label="Permalink to &quot;3. 临床 AI 深度推理预测问诊失败&quot;">​</a></h3><p>医疗研究指出大模型 问诊面临痛点 存在硬伤。随着推理步数增加模型表现 (⊙﹏⊙) 下滑。即使是新框架也难以有效处理 深层推理 。这种瓶颈限制了临床 ฅ^•ﻌ•^ฅ 场景快速落地。研究为评估临床 AI 提供了全新理论。 来源：<a href="https://arxiv.org/abs/2606.16890" target="_blank" rel="noreferrer">arxiv.org</a></p><h3 id="_4-几何运动学揭秘大模型推理轨迹" tabindex="-1">4. 几何运动学揭秘大模型推理轨迹 <a class="header-anchor" href="#_4-几何运动学揭秘大模型推理轨迹" aria-label="Permalink to &quot;4. 几何运动学揭秘大模型推理轨迹&quot;">​</a></h3><p>科研团队推出全新平台 🔬 剖析推理逻辑。大家可阅读 大模型推理分析 论文详情。稳定逻辑轨迹 (๑•̀ㅂ•́) 是正确推理的前提。而幻觉常常伴随着 😵‍💫 频繁波动与逻辑停滞。该工作为解码机器思维动态提供全新物理视角。 来源：<a href="https://arxiv.org/abs/2603.10384" target="_blank" rel="noreferrer">arxiv.org</a></p><h3 id="_5-anthropic-智能体编码中专业知识回报持续存在" tabindex="-1">5. Anthropic：智能体编码中专业知识回报持续存在 <a class="header-anchor" href="#_5-anthropic-智能体编码中专业知识回报持续存在" aria-label="Permalink to &quot;5. Anthropic：智能体编码中专业知识回报持续存在&quot;">​</a></h3><p>Anthropic 基于约 40 万次 Claude Code 交互会话（2025 年 10 月至 2026 年 4 月）分析发现：人类主导规划决策（做什么），Claude 主导执行决策（怎么做）。领域专业知识越强，模型每次指令完成的工作量越多。各类职业完成任务的成功率与软件工程师平均相近；领域专家成功率更高，但与中级用户差距不大。七个月间调试会话占比下降近一半，使用转向端到端智能体任务（部署运行代码、分析数据、编写非代码文档），典型任务价值平均上升约 25%。 🧠 来源：<a href="https://www.anthropic.com/research/claude-code-expertise" target="_blank" rel="noreferrer">anthropic.com</a></p><h3 id="_6-openai-发布-deployment-simulation-方法-通过模拟部署预测模型发布前行为" tabindex="-1">6. OpenAI 发布 Deployment Simulation 方法：通过模拟部署预测模型发布前行为 <a class="header-anchor" href="#_6-openai-发布-deployment-simulation-方法-通过模拟部署预测模型发布前行为" aria-label="Permalink to &quot;6. OpenAI 发布 Deployment Simulation 方法：通过模拟部署预测模型发布前行为&quot;">​</a></h3><p>OpenAI 近日发布 Deployment Simulation 方法，通过在隐私保护下重放历史对话、用新候选模型重新生成回复，模拟模型上线后的实际表现。在多个 GPT‑5‑series Thinking 部署中，该方法比传统评估更准确地估计了不良行为频率，发现新型对齐问题，并降低模型识别测试的风险。它还能扩展至涉及工具使用的智能体场景。传统评估存在覆盖不足、选择偏差和模型可识别测试等局限，而 Deployment Simulation 使用真实对话分布缓解了这些问题，但无法测量频率低于每 20 万条消息 1 次的行为。 🧠 来源：<a href="https://openai.com/index/deployment-simulation" target="_blank" rel="noreferrer">openai.com</a></p><h3 id="_7-公开聊天数据能否预测真实世界-ai-失调" tabindex="-1">7. 公开聊天数据能否预测真实世界 AI 失调？ <a class="header-anchor" href="#_7-公开聊天数据能否预测真实世界-ai-失调" aria-label="Permalink to &quot;7. 公开聊天数据能否预测真实世界 AI 失调？&quot;">​</a></h3><p>OpenAI 利用 WildChat 公开数据集（2023 年 4 月至 2024 年 5 月收集的 100 万条对话）模拟模型部署，预测 GPT-5.1、GPT-5.2、GPT-5.4 在真实生产环境中的不良行为率。与私有生产数据对比发现，WildChat 模拟的平均预测误差约 3 倍；但对技术性和智能体型失调的预测精度下降。研究验证了公开数据集作为外部审计工具的可行性。 🧠 来源：<a href="https://alignment.openai.com/validating-public-evals" target="_blank" rel="noreferrer">alignment.openai.com</a></p><h2 id="行业、政策与安全" tabindex="-1">行业、政策与安全 <a class="header-anchor" href="#行业、政策与安全" aria-label="Permalink to &quot;行业、政策与安全&quot;">​</a></h2><h3 id="_1-g7-国家或将共享前沿-ai-模型" tabindex="-1">1. G7 国家或将共享前沿 AI 模型 <a class="header-anchor" href="#_1-g7-国家或将共享前沿-ai-模型" aria-label="Permalink to &quot;1. G7 国家或将共享前沿 AI 模型&quot;">​</a></h3><p>西方首脑正密谋开放 美系模型 。点击 获取系统权限 即可看最新提议。此举试图用准入额度 😲 换取部分禁令豁免。科技巨头博弈中 (ﾟ ∀ ﾟ) 寻找全新算力出口。外交官称这旨再稳固西方的算法霸权。 来源：<a href="https://www.reuters.com/technology/artificial-intelligence/" target="_blank" rel="noreferrer">Reuters</a></p><h3 id="_2-创意软件巨头发布年度报告" tabindex="-1">2. 创意软件巨头发布年度报告 <a class="header-anchor" href="#_2-创意软件巨头发布年度报告" aria-label="Permalink to &quot;2. 创意软件巨头发布年度报告&quot;">​</a></h3><p>报告覆盖一万多 🚀 用户样本量。绝大多数创作者觉得全新工具让业务 📈 飞起。约有七五成的人已经离不开 (๑•̀ㅂ•) 智能流。点击看 年度报告详细数据 揭示了哪些新动向。这些新潮流正改变着我们创作者的习惯。 来源：<a href="https://news.adobe.com/news/2026/06/creators-toolkit-report-2026" target="_blank" rel="noreferrer">news.adobe.com</a></p><h3 id="_3-大模型平台明年预估亏损爆棚" tabindex="-1">3. 大模型平台明年预估亏损爆棚 <a class="header-anchor" href="#_3-大模型平台明年预估亏损爆棚" aria-label="Permalink to &quot;3. 大模型平台明年预估亏损爆棚&quot;">​</a></h3><p>最新 平台财务数据 表明其亏损规模巨大。亏损数字相比去年直接翻了八倍 🚀 那么惊人。高额算力设备与人才 (｡･ω･｡) 成本是核心原因。行业大咖纷纷质疑这种疯狂烧钱模式是否持久。 来源：<a href="https://www.wheresyoured.at/exclusive-openai-financials/" target="_blank" rel="noreferrer">wheresyoured.at</a></p><h3 id="_4-微软旗下-github-遭遇-ai-算力短缺-转而向-aws-寻求支持" tabindex="-1">4. 微软旗下 GitHub 遭遇 AI 算力短缺，转而向 AWS 寻求支持 <a class="header-anchor" href="#_4-微软旗下-github-遭遇-ai-算力短缺-转而向-aws-寻求支持" aria-label="Permalink to &quot;4. 微软旗下 GitHub 遭遇 AI 算力短缺，转而向 AWS 寻求支持&quot;">​</a></h3><p>微软旗下 GitHub 面临 AI 算力短缺，微软因此转向亚马逊 AWS 寻求计算资源支持。原文来自 Hacker News 热门讨论，标题为“Microsoft turns to AWS as GitHub faces AI capacity crunch”。 ⚖️ 来源：<a href="https://runtimewire.com/article/microsoft-github-aws-ai-capacity-crunch" target="_blank" rel="noreferrer">runtimewire.com</a></p><h3 id="_5-anthropic-5-月企业-ai-订阅份额首超-openai-特朗普政府禁令反促采用量创新高" tabindex="-1">5. Anthropic 5 月企业 AI 订阅份额首超 OpenAI，特朗普政府禁令反促采用量创新高 <a class="header-anchor" href="#_5-anthropic-5-月企业-ai-订阅份额首超-openai-特朗普政府禁令反促采用量创新高" aria-label="Permalink to &quot;5. Anthropic 5 月企业 AI 订阅份额首超 OpenAI，特朗普政府禁令反促采用量创新高&quot;">​</a></h3><p>Anthropic 5 月企业 AI 订阅市场份额达 41%，首次超越 OpenAI（39.5%）。公司刚完成 650 亿美元融资、估值 9650 亿美元，并因首次盈利季度秘密提交 IPO。特朗普政府以出口管制为由要求 Anthropic 禁止非美国人访问最新模型 Mythos 5 及 Fable 5，导致两款模型下架。Ramp 首席经济学家指出，类似争议（如 3 月被国防部列为供应链风险）反而推动 Anthropic 企业采用量创纪录。Ramp 数据显示，企业支出主要流向 Claude Opus 模型（最新为 Opus 4.8）。 ⚖️ 来源：<a href="https://techcrunch.com/2026/05/13/anthropic-now-has-more-business-customers-than-openai-according-to-ramp-data/" target="_blank" rel="noreferrer">TechCrunch</a></p><h3 id="_6-tim-ferriss-称-ai-冲击导致书籍销量暴跌" tabindex="-1">6. Tim Ferriss 称 AI 冲击导致书籍销量暴跌 <a class="header-anchor" href="#_6-tim-ferriss-称-ai-冲击导致书籍销量暴跌" aria-label="Permalink to &quot;6. Tim Ferriss 称 AI 冲击导致书籍销量暴跌&quot;">​</a></h3><p>知名作家 Tim Ferriss 揭露其书籍销量在近期遭遇了 断崖式下跌 。 去年 非虚构类书籍 销量减半 😲 令人感到非常地愕然。 人工智能 正在深刻改变读者的习惯并取代传统书本。 这种 (⊙o⊙) 知识获取 方式变了让出书的感到了巨大压力。 这种跌幅暗示着 AI 工具 已经成为获取实用技能的首选。 来源：<a href="https://tim.blog/2026/06/12/has-ai-already-killed-nonfiction/" target="_blank" rel="noreferrer">Tim Ferriss</a></p><p><img src="`+n+'" alt="AI资讯：展示书籍销量断崖式下跌趋势的数据图表" loading="lazy"></p><h3 id="_7-美国司法部援引国家安全为-xai-未经许可的燃气轮机辩护" tabindex="-1">7. 美国司法部援引国家安全为 xAI 未经许可的燃气轮机辩护 <a class="header-anchor" href="#_7-美国司法部援引国家安全为-xai-未经许可的燃气轮机辩护" aria-label="Permalink to &quot;7. 美国司法部援引国家安全为 xAI 未经许可的燃气轮机辩护&quot;">​</a></h3><p>美国司法部在一份驳回诉讼的动议中称，xAI 的聊天机器人 Grok 对军事行动至关重要，以此为其在密西西比州 Southaven 的 Colossus 2 设施运行未经许可的燃气轮机辩护。NAACP 已提起诉讼，指控 xAI 的燃气轮机数量从 4 月的 27 台增至 57 台，导致氮氧化物排放飙升 111%。国防部首席数字与人工智能官 Cameron Stanley 表示，Grok 是支持机密和绝密网络军事任务的四款 AI 模型之一，包括近期针对伊朗的打击。 ⚖️ 来源：<a href="https://techcrunch.com/2026/06/16/doj-claims-xais-unpermitted-gas-turbines-are-a-matter-of-national-economic-and-energy-security/" target="_blank" rel="noreferrer">TechCrunch</a></p><h3 id="_8-微软考虑为-copilot-cowork-集成-deepseek-v4" tabindex="-1">8. 微软考虑为 Copilot Cowork 集成 DeepSeek V4 <a class="header-anchor" href="#_8-微软考虑为-copilot-cowork-集成-deepseek-v4" aria-label="Permalink to &quot;8. 微软考虑为 Copilot Cowork 集成 DeepSeek V4&quot;">​</a></h3><p>微软正考虑为 Copilot Cowork 提供微软托管的 DeepSeek V4 版本，作为更便宜的模型选项。Copilot Cowork 将放弃无限定价，转向按使用量计费，原因是成本过高（用户每周执行数百项任务导致费用激增）。若采用 DeepSeek，该模型将是可选的、经过微调与安全防护，并完全托管于 Azure。Axios 报道称微软已微调了一个可用模型，最终决定待定。 ⚖️ 来源：<a href="https://www.axios.com/2026/06/16/microsoft-copilot-cowork-tokenmaxxing-cowork" target="_blank" rel="noreferrer">Axios</a></p><h3 id="_9-fable-遭美国政府封禁-techcrunch-质疑真正原因并非模型越狱" tabindex="-1">9. Fable 遭美国政府封禁，TechCrunch 质疑真正原因并非模型越狱 <a class="header-anchor" href="#_9-fable-遭美国政府封禁-techcrunch-质疑真正原因并非模型越狱" aria-label="Permalink to &quot;9. Fable 遭美国政府封禁，TechCrunch 质疑真正原因并非模型越狱&quot;">​</a></h3><p>美国政府对 Anthropic 的模型 Fable 实施封禁，但 TechCrunch 发文质疑，实际原因可能并非此前认为的“模型越狱”问题。该文章在 Hacker News 引发讨论，获得 103 个点赞。 ⚖️ 来源：<a href="https://techcrunch.com/2026/06/15/the-us-governments-anthropic-models-ban-was-never-about-an-ai-jailbreak/" target="_blank" rel="noreferrer">TechCrunch</a></p><h3 id="_10-spacex-以-600-亿美元股票收购-ai-编程公司-cursor" tabindex="-1">10. SpaceX 以 600 亿美元股票收购 AI 编程公司 Cursor <a class="header-anchor" href="#_10-spacex-以-600-亿美元股票收购-ai-编程公司-cursor" aria-label="Permalink to &quot;10. SpaceX 以 600 亿美元股票收购 AI 编程公司 Cursor&quot;">​</a></h3><p>SpaceX 在历史性 IPO 数天后，同意以 600 亿美元股票收购 AI 编程初创公司 Cursor，旨在帮助其围绕 xAI 构建的 AI 部门追赶主要 AI 实验室。此前 Cursor 正接近完成一轮 20 亿美元融资，估值 500 亿美元，投资方包括 Andreessen Horowitz、Thrive 和 Nvidia。SpaceX 在 IPO 期间向投资者表示，其 AI 产品可寻址市场达 26 万亿美元。交易预计于今年第三季度完成。 ⚖️ 来源：<a href="https://techcrunch.com/2026/06/16/spacex-to-acquire-cursor-for-60b-in-stock-days-after-blockbuster-ipo/" target="_blank" rel="noreferrer">TechCrunch</a></p><h3 id="_11-deepseek-完成首轮外部融资-估值超-500-亿美元" tabindex="-1">11. DeepSeek 完成首轮外部融资，估值超 500 亿美元 <a class="header-anchor" href="#_11-deepseek-完成首轮外部融资-估值超-500-亿美元" aria-label="Permalink to &quot;11. DeepSeek 完成首轮外部融资，估值超 500 亿美元&quot;">​</a></h3><p>中国 AI 初创公司 DeepSeek 完成首轮外部融资，募资超 500 亿元人民币（约 74 亿美元），估值超 500 亿美元。投资结构特殊：多数投资者将资金投入 CEO 梁文锋管理的有限合伙企业，无投票权且锁定期五年；仅国资 AI 基金直接投资并保留投票权。创始人梁文锋个人投入约 200 亿元，腾讯和宁德时代为主要外部投资者。梁文锋表示优先基础 AI 研究与 AGI 开发，将继续开源。DeepSeek 去年初凭 V3、R1 模型获全球关注，今年 4 月发布运行于华为芯片的最大开源权重模型 V4，并将 V4 Pro 永久折扣 75%，输入价格约为 OpenAI GPT-5.5 的 1/11，输出价格约为 1/35。 ⚖️ 来源：<a href="https://the-decoder.com/deepseek-takes-outside-money-for-the-first-time-at-a-50-billion-valuation/" target="_blank" rel="noreferrer">The Decoder</a></p><h2 id="开源与开发者工具" tabindex="-1">开源与开发者工具 <a class="header-anchor" href="#开源与开发者工具" aria-label="Permalink to &quot;开源与开发者工具&quot;">​</a></h2><h3 id="_1-高性能极轻量级内存向量库开源" tabindex="-1">1. 高性能极轻量级内存向量库开源 <a class="header-anchor" href="#_1-高性能极轻量级内存向量库开源" aria-label="Permalink to &quot;1. 高性能极轻量级内存向量库开源&quot;">​</a></h3><p>大厂推出了超轻量级 zvec 数据库。该 高分开源项目 性能极其炸裂。它运行极快 ⚡️ 且完全常驻在进程内存中。这能帮助大模型高效 🚀 搞定各种语义检索。开发者用它能更轻便地构建检索应用。 来源：<a href="https://github.com/alibaba/zvec" target="_blank" rel="noreferrer">GitHub</a></p><h3 id="_2-多语言语音生成模型正式发布" tabindex="-1">2. 多语言语音生成模型正式发布 <a class="header-anchor" href="#_2-多语言语音生成模型正式发布" aria-label="Permalink to &quot;2. 多语言语音生成模型正式发布&quot;">​</a></h3><p>全新开源平台提供 多语言语音生成 代码。该项目针对语音克隆 🤖 开发了硬核科技。它能实现超真声音克隆 (๑•̀ㅂ•稳) 进度极快。目前在开源社区已经疯狂斩获三万星标。免分词技术大大加速了配音产业迭代。 来源：<a href="https://github.com/OpenBMB/VoxCPM" target="_blank" rel="noreferrer">GitHub</a></p><p><img src="'+i+'" alt="AI资讯：开源多语言语音生成大模型VoxCPM2端到端无缝克隆声音的技术架构原理图" loading="lazy"></p><h3 id="_3-从零构建大模型实战指南爆火" tabindex="-1">3. 从零构建大模型实战指南爆火 <a class="header-anchor" href="#_3-从零构建大模型实战指南爆火" aria-label="Permalink to &quot;3. 从零构建大模型实战指南爆火&quot;">​</a></h3><p>该 AI 工程实战指南 在 GitHub 上人气超高。教程全面覆盖了 🛠️ 研发到上线的核心环节。初学者在此能轻松上手大名鼎鼎的 RAG 架构 。该指南已斩获超 (๑•̀ㅂ•́) 三万星标持续霸榜。这绝对是工程师们逆袭的必备利器。 来源：<a href="https://github.com/rohitg00/ai-engineering-from-scratch" target="_blank" rel="noreferrer">GitHub</a></p><h2 id="社媒与观点" tabindex="-1">社媒与观点 <a class="header-anchor" href="#社媒与观点" aria-label="Permalink to &quot;社媒与观点&quot;">​</a></h2><h3 id="_1-人类亟需在爆发前建立验证体系" tabindex="-1">1. 人类亟需在爆发前建立验证体系 <a class="header-anchor" href="#_1-人类亟需在爆发前建立验证体系" aria-label="Permalink to &quot;1. 人类亟需在爆发前建立验证体系&quot;">​</a></h3><p>知名人士在 大牌周刊上 发出了全新警告。我们 🛡️ 还没完全准备好应对智能大爆发。必须在自我进化 🚀 之前建成有效约束机制。该协调过程 😰 虽然艰巨但并非没有机会。点击看 最新呼吁倡议 各国合作 (｡•̀ᴗ-)✧ 执行。 来源：<a href="https://www.economist.com/by-invitation/2026/06/15/humanity-isnt-ready-for-the-coming-intelligence-explosion" target="_blank" rel="noreferrer">economist.com</a></p><p><img src="'+l+'" alt="AI资讯：经济学人关于全球如何协同防范超级智能爆炸与安全失控风险的警告插图" loading="lazy"></p><h3 id="_2-okara-首发网红智能体" tabindex="-1">2. Okara 首发网红智能体 <a class="header-anchor" href="#_2-okara-首发网红智能体" aria-label="Permalink to &quot;2. Okara 首发网红智能体&quot;">​</a></h3><p>Okara 发布首个网红智能体，将繁琐的达人营销转化为自动化软件流程 🚀 极其丝滑。 智能网红营销工具 能精准筛选博主并自动发送合作邀约。 智能体 Agent 深度参与从合同签署到支付结算的全部核心业务环节 (・ω・)b 效率极高。 用户输入需求即可在 推文原文详情 中见证内容自动发布。 这种基于规则的 结构化混乱 领域正被 AI 彻底接管 ✨ 真的太强悍了。 来源：<a href="https://okara.ai/influencer" target="_blank" rel="noreferrer">okara.ai</a></p><p><video src="'+s+'" controls="controls" width="100%"></video></p><h3 id="_3-支付宝推出-ai-重构极简版" tabindex="-1">3. 支付宝推出 AI 重构极简版 <a class="header-anchor" href="#_3-支付宝推出-ai-重构极简版" aria-label="Permalink to &quot;3. 支付宝推出 AI 重构极简版&quot;">​</a></h3><p>大厂 ⚡️ 灰度测试 支付宝正式推出极简 AI 版本 该版本 🚀 彻底重构首页功能入口 😱 这意味着 降本增效 将成为支付巨头 💰 核芯战略 外界猜测 😲 支付宝运营团队 💼 规摸会大幅缩减 网友直言 智能助手 应该聚焦于支付场景 (^_^)v 来源：<a href="https://m.okjike.com/originalPosts/6a30d2d79ff12df4b798d322" target="_blank" rel="noreferrer">m.okjike.com</a></p><p><img src="'+h+'" alt="AI资讯：支付宝AI版界面显示简洁对话框" loading="lazy"></p><h3 id="_4-标准化-ai-开发流程" tabindex="-1">4. 标准化 AI 开发流程 <a class="header-anchor" href="#_4-标准化-ai-开发流程" aria-label="Permalink to &quot;4. 标准化 AI 开发流程&quot;">​</a></h3><p>马特发布 人工智能开发流程 。 从 摸糊想法 💡 过度到代码实现。 利用 工具 深度折解复杂需求。 这让 智能体执行 🚀 效率质变。 戳 干货细节 ✌️。 来源：<a href="https://github.com/mattpocock/skills" target="_blank" rel="noreferrer">GitHub</a></p><p><img src="'+c+'" alt="AI资讯:马特提出的开发七阶段核心架构图" loading="lazy"></p><h3 id="快讯" tabindex="-1">快讯 <a class="header-anchor" href="#快讯" aria-label="Permalink to &quot;快讯&quot;">​</a></h3><ul><li><strong>大模型融入银行协议玩转自动化</strong>：极客在推特展示了 自动管账细节 处理公司业务。用户仅需对话 💻 就能完成全部发票对账。这种全新原生金融 🤖 让财务人感到非常惊讶。智能代理全托管 (⊙o⊙) 正成为落地热点。 来源：<a href="https://www.reddit.com/r/ClaudeAI/comments/1u7p0g6/saw_someone_managing_their_entire_business/" target="_blank" rel="noreferrer">reddit.com</a></li><li><strong>微软微调 DeepSeek 挑战 OpenAI 地位</strong>：微软已秘密微调 DeepSeek 模型 🚀 性能极佳。 它是 微软引入 DeepSeek 低价替代品。 这标志着微软与 OpenAI 盟友关系生变 (๑•̀ㅂ•́)و✧。 官方考虑转向 按量计费 的计价新模式。 巨头们试图通过多元化模型降低 推理成本 。 来源：<a href="https://x.com/AndrewCurran_/status/2066939401725501590" target="_blank" rel="noreferrer">x.com</a></li><li><strong>资本远期做空劳动议价权引发 AI 裁员潮</strong>：科技巨头正掀起名为 效率革命 的 AI 裁员潮 。 资本利用 削弱劳方议价权 进行远期做空。 虽然 AI 替代 未兑现但劳动定价已被提前重塑 ⊙o⊙。 这种不对称赔率让大厂敢于裁员 📉 以维持利润增长。 本质上这就是一场针对 普通打工人 的无情 💸 资本游戏 。 来源：<a href="https://mp.weixin.qq.com/s/vZpxTB3MBav8vtqDR3U6Nw" target="_blank" rel="noreferrer">mp.weixin.qq.com</a></li><li><strong>Meta 解散工程部门引发热议</strong>：6 月 16 日，一篇标题为“Why is Meta destroying its engineering organization?”的博客文章出现在 Hacker News，获得 110 个点赞。文章指出 Meta 正在解散其工程组织，引发业界广泛讨论。具体原因和后续影响尚未明确。 来源：<a href="https://newsletter.pragmaticengineer.com/p/why-is-meta-destroying-its-engineering" target="_blank" rel="noreferrer">newsletter.pragmaticengineer.com</a></li><li><strong>毕业生陷入 AI 检测荒诞循环：手写摘要被判 99%AI 率，AI 写部分 0%</strong>：当前毕业生面临论文 AIGC 率检测荒诞困境。学生手写摘要被判定 99%AI 率，纯 AI 写部分却为 0%。学校要求 AIGC 率不超 40%，学生用 Claude 反复修改并花上百元检测费（维普 20 元/篇，知网/万方 2 元/千字符），最终降至 36.1%。答辩时老师要求改回学术表达，AI 率回升至 37.21%。同一论文在不同平台检测结果差异巨大（48%、44%、59%）。部分平台提供降重收费服务，少数学校已改用 AI 使用声明表替代一刀切检测。 来源：<a href="https://mp.weixin.qq.com/s/DRzNIiojGLO-iqqPyJ7f8Q" target="_blank" rel="noreferrer">mp.weixin.qq.com</a></li><li><strong>WorkBuddy 日活飙升至行业第二的 3-4 倍，非技术用户涌入</strong>：从 3 月至今，WorkBuddy 日活用户数已达行业第二名的 3-4 倍，用户不再限于开发者，大量 HR、运营、行政等非技术岗位也在使用。其企业版和项目功能进一步扩展了 Agent 办公场景。同期，Trae Work、QoderWork、Kimi Work 等产品纷纷改名或出新，争夺市场。腾讯云认为这可能是十年一遇的机遇。 来源：<a href="https://mp.weixin.qq.com/s/iAgbUzPrsbpqvu4s2XiH0g" target="_blank" rel="noreferrer">mp.weixin.qq.com</a></li><li><strong>OpenAI 的领先优势正在快速缩小</strong>：评论认为 OpenAI 正面临多重危机：缺乏护城河导致市场领先地位下滑；最大投资者微软持续疏远，近期甚至公开考虑将主要产品外包给中国；亏损速度远超预期，年亏损额以 8 倍增长。华盛顿方面可能打压 Anthropic，但也可能反而帮助其崛起，而 Elon Musk 成为另一个潜在的竞标者。 来源：<a href="https://garymarcus.substack.com/p/openais-lead-is-dwindling-fast" target="_blank" rel="noreferrer">garymarcus.substack.com</a></li><li><strong>前沿大模型后训练配方回顾：与 Finbarr Timbers 对谈</strong>：Interconnects 播客邀请 Finbarr Timbers 回顾后训练配方的演变：从 InstructGPT 的 SFT→ 奖励模型 →RL 三阶段，到 Llama 3 / Tülu 3 的 SFT→DPO→ 可验证奖励 RL，再至 DeepSeek R1 以大规模 RL 为核心。2026 年配方分化为多个领域专家模型再合并回统一模型。新出现模式为 Multi-teacher On-Policy Distillation（MOPD）：训练 N 个领域专家（经 SFT 和领域 RL），再通过在线采样、逐 token 最小化反向 KL 散度训练通用学生模型。MiMo Flash V2 率先引入，DeepSeek V4 与 Nemot… 来源：<a href="https://www.interconnects.ai/p/frontier-post-training-recipe-review" target="_blank" rel="noreferrer">interconnects.ai</a></li></ul><h2 id="今日总结与启示" tabindex="-1">今日总结与启示 <a class="header-anchor" href="#今日总结与启示" aria-label="Permalink to &quot;今日总结与启示&quot;">​</a></h2><ul><li><strong>产品开始围绕完整任务重组。</strong> 单点模型能力正在被封装进可执行、可协作的工作流 🚀。</li><li><strong>研究价值更依赖可复现证据。</strong> 论文、基准和官方技术报告仍是判断进展的核心依据 🧠。</li><li><strong>算力与商业约束同步上升。</strong> 电力、推理成本、融资和定价会直接影响产品路线 ☁️。</li><li><strong>政策与安全边界持续变化。</strong> 企业需要把合规、供应链和模型可用性纳入架构设计 ⚖️。</li><li><strong>开源工具仍是落地最快的抓手。</strong> 可嵌入组件和工程框架正在缩短从实验到生产的距离 🛠️。</li></ul>',94)])])}const w=a(p,[["render",d]]);export{_ as __pageData,w as default};
